@Component("operator-handler")
@ProcessingGroup("operator-processing-group")
public class OperatorEventHandler {
	
	// core constructor
	OperatorEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOperatorEvent
     */
    @EventHandler
    public void handle( CreateOperatorEvent event) {
        entityManager.persist(new Operator(event.getOperatorId(), event.getName(), event.getIcaoDesignator(), event.getAircraftOrders(), event.getOperatedAircraft(), event.getSalesRegion(), event.getOperatorType()));
    }

    /*
     * @param	event UpdateOperatorEvent
     */
    @EventHandler
    public Operator handle( UpdateOperatorEvent event) {
    	entityManager.merge(new Operator(event.getOperatorId(), event.getName(), event.getIcaoDesignator(), event.getAircraftOrders(), event.getOperatedAircraft(), event.getSalesRegion(), event.getOperatorType()));
    }
    
    /*
     * @param	event DeleteOperatorEvent
     */
    @EventHandler
    public void on( DeleteOperatorEvent event) {
    	Operator entity = new Operator();
   
    	// ------------------------------------------
    	// apply the OperatorId
    	// ------------------------------------------
    	entity.setOperatorId( event.getOperatorId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OperatorRepository operatorEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OperatorEventHandler.class.getName());

}
